(function(){'use strict';var i18n=window.smileTheme||{};function initNav(){var toggle=document.querySelector('.smile-nav-toggle');var nav=document.getElementById('smile-primary-nav');if(!toggle||!nav){return;}
var label=toggle.querySelector('.smile-nav-toggle__label');var backdrop=null;var mq=window.matchMedia('(max-width: 1200px)');function setOpen(open){toggle.setAttribute('aria-expanded',open?'true':'false');nav.classList.toggle('is-open',open);document.body.classList.toggle('smile-nav-open',open);if(label){label.textContent=open?(i18n.menuClose||'Close menu'):(i18n.menuOpen||'Open menu');}
if(open){backdrop=document.createElement('div');backdrop.className='smile-nav-backdrop';backdrop.addEventListener('click',function(){setOpen(false);toggle.focus();});document.body.appendChild(backdrop);var first=nav.querySelector('a, button');if(first){first.focus();}}else if(backdrop){backdrop.remove();backdrop=null;}}
toggle.addEventListener('click',function(){setOpen(toggle.getAttribute('aria-expanded')!=='true');});document.addEventListener('keydown',function(e){if(e.key==='Escape'&&nav.classList.contains('is-open')){setOpen(false);toggle.focus();}});nav.addEventListener('keydown',function(e){if(e.key!=='Tab'||!nav.classList.contains('is-open')){return;}
var items=nav.querySelectorAll('a, button');if(!items.length){return;}
var first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();toggle.focus();}
else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();toggle.focus();}});nav.querySelectorAll('.menu-item-has-children').forEach(function(item,i){var link=item.querySelector(':scope > a');var sub=item.querySelector(':scope > .sub-menu');if(!link||!sub){return;}
var id='smile-sub-'+i;sub.id=id;var btn=document.createElement('button');btn.type='button';btn.className='smile-sub-toggle';btn.setAttribute('aria-expanded','false');btn.setAttribute('aria-controls',id);btn.innerHTML='<span class="screen-reader-text">'+link.textContent+'</span><span aria-hidden="true">+</span>';link.insertAdjacentElement('afterend',btn);btn.addEventListener('click',function(){var open=btn.getAttribute('aria-expanded')!=='true';btn.setAttribute('aria-expanded',open?'true':'false');item.classList.toggle('is-open',open);btn.querySelector('[aria-hidden]').textContent=open?'\u2212':'+';});});mq.addEventListener('change',function(e){if(!e.matches){setOpen(false);}});}
function initCopy(){document.addEventListener('click',function(e){var btn=e.target.closest('[data-smile-copy]');if(!btn){return;}
var value=btn.getAttribute('data-smile-copy');var original=btn.getAttribute('data-label')||btn.textContent;btn.setAttribute('data-label',original);var done=function(ok){btn.textContent=ok?(i18n.copied||'Copied'):(i18n.copyFail||'Press and hold to copy');btn.classList.toggle('is-copied',ok);var live=document.getElementById('smile-live');if(live){live.textContent=ok?value+' '+(i18n.copied||'Copied'):'';}
setTimeout(function(){btn.textContent=original;btn.classList.remove('is-copied');},2200);};if(navigator.clipboard&&window.isSecureContext){navigator.clipboard.writeText(value).then(function(){done(true);},function(){done(false);});}else{done(false);}});}
function initScroll(){var header=document.getElementById('site-header');if(!header){return;}
var ticking=false;var update=function(){header.classList.toggle('is-scrolled',window.scrollY>40);ticking=false;};window.addEventListener('scroll',function(){if(!ticking){ticking=true;window.requestAnimationFrame(update);}},{passive:true});update();}
function initReveal(){var items=document.querySelectorAll('.smile-reveal');if(!items.length){return;}
if(!('IntersectionObserver'in window)||window.matchMedia('(prefers-reduced-motion: reduce)').matches){items.forEach(function(el){el.classList.add('is-in');});return;}
var io=new IntersectionObserver(function(entries){entries.forEach(function(e){if(e.isIntersecting){e.target.classList.add('is-in');io.unobserve(e.target);}});},{rootMargin:'0px 0px -8% 0px',threshold:0.08});items.forEach(function(el,i){if(!el.style.getPropertyValue('--i')){el.style.setProperty('--i',String(i%4));}
io.observe(el);});}
function initSmiles(){var ems=document.querySelectorAll('.elementor-heading-title em, .smile-slide__title em, .smile-ctaphoto h2 em');if(!ems.length){return;}
var reduce=window.matchMedia('(prefers-reduced-motion: reduce)').matches;ems.forEach(function(em){if(em.querySelector('.smile-swash')){return;}
em.classList.add('smile-em');em.insertAdjacentHTML('beforeend','<svg class="smile-swash" viewBox="0 0 200 24" preserveAspectRatio="none" aria-hidden="true" focusable="false"><path d="M4 8 C 45 22, 150 24, 196 5"/></svg>');});if(reduce||!('IntersectionObserver'in window)){ems.forEach(function(em){em.classList.add('is-drawn');});return;}
var io=new IntersectionObserver(function(entries){entries.forEach(function(e){if(e.isIntersecting){e.target.classList.add('is-drawn');io.unobserve(e.target);}});},{threshold:0.6});ems.forEach(function(em){io.observe(em);});}
function initCalc(){document.querySelectorAll('.smile-calc').forEach(function(root){var meal=parseFloat(root.getAttribute('data-meal'))||500;var water=parseFloat(root.getAttribute('data-water'))||2500;var fees=parseFloat(root.getAttribute('data-fees'))||15000;var usd=parseFloat(root.getAttribute('data-usd'))||100;var input=root.querySelector('input[type="number"]');var chips=root.querySelectorAll('.smile-calc__chip');var fmt=function(n){return Math.round(n).toLocaleString('en-KE');};var out=function(k){return root.querySelector('[data-out="'+k+'"]');};function render(amount){amount=Math.max(0,Math.round(amount||0));out('amount').textContent='KES '+fmt(amount);out('usd').textContent='about US$'+fmt(amount/usd);out('amount-plain').textContent=fmt(amount);out('amount-copy').setAttribute('data-smile-copy',String(amount));var days=amount/meal;out('meals').textContent=days>=1?fmt(days):'1';var weeks=amount/water;out('water').textContent=weeks>=1?fmt(weeks):(weeks>=0.5?'half a':'part of a');out('water-unit').textContent=weeks>=2?'weeks':'week';out('fees').hidden=amount<fees;chips.forEach(function(c){var on=parseInt(c.getAttribute('data-amount'),10)===amount;c.classList.toggle('is-active',on);c.setAttribute('aria-pressed',on?'true':'false');});}
chips.forEach(function(c){c.addEventListener('click',function(){var a=parseInt(c.getAttribute('data-amount'),10);input.value=a;render(a);});});input.addEventListener('input',function(){render(parseFloat(input.value));});render(parseFloat(input.value));});}
function initTabbarMenu(){var btn=document.querySelector('[data-smile-open-menu]');var toggle=document.querySelector('.smile-nav-toggle');if(btn&&toggle){btn.addEventListener('click',function(){toggle.click();});}}
function initForms(){var target=document.querySelector('.smile-form__status[tabindex="-1"]');if(target){target.focus();}}
if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',function(){initNav();initCopy();initForms();initScroll();initReveal();initSmiles();initCalc();initTabbarMenu();});}else{initNav();initCopy();initForms();initScroll();initReveal();initSmiles();initCalc();initTabbarMenu();}}());